import os, json
class KV:
    def __init__(self, path):
        self.path, self.mem = path, {}
        if os.path.exists(path):
            for line in open(path):
                op, k, *v = json.loads(line)
                if op == 'put': self.mem[k] = v[0]
                else: self.mem.pop(k, None)
    def _log(self, rec):
        with open(self.path, 'a') as f:
            f.write(json.dumps(rec) + '\n'); f.flush(); os.fsync(f.fileno())
    def put(self, k, v): self._log(['put', k, v]); self.mem[k] = v
    def delete(self, k): self._log(['del', k]); self.mem.pop(k, None)
    def get(self, k): return self.mem.get(k)
    def compact(self):
        tmp = self.path + '.tmp'
        with open(tmp, 'w') as f:
            for k, v in self.mem.items(): f.write(json.dumps(['put', k, v]) + '\n')
